sum by (image_spec) (
  label_replace(
    kube_pod_container_info{container!="", pod=~"^$service.*"}
    * on(pod) group_left(rems_service) (
      kube_pod_labels{rems_service!=""}
    ),
    "image", "$1", "image", ".*/([^:]+).*"
  )
)

(
    sum(
        rate(
            traces_span_metrics_duration_milliseconds_count{
                rems_application_group="$ApplicationGroup",
                rems_service="$service",
                rems_environment="$env",
                span_kind="SPAN_KIND_SERVER",
                http_status_code=~"^2.*|^3.*",
                http_route=~"$route"
            }[5m]
        ) or on() vector(0)
    )
    +
    sum(
        rate(
            traces_span_metrics_duration_milliseconds_count{
                rems_application_group="$ApplicationGroup",
                rems_service="$service",
                rems_environment="$env",
                span_kind="SPAN_KIND_SERVER",
                rpc_grpc_status_code=~"0|1",
                http_route=~"$route"
            }[5m]
        ) or on() vector(0)
    )
)
* 100
/
sum(
    rate(
        traces_span_metrics_duration_milliseconds_count{
            span_kind="SPAN_KIND_SERVER",
            rems_application_group="$ApplicationGroup",
            rems_service="$service",
            rems_environment="$env",
            http_route=~"$route"
        }[5m]
    )
)

